"use client";

import React from "react";
import { Sparkles } from "lucide-react";
import { cn } from "@/lib/utils";

export interface ShinyButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  label?: string;
}

export function ShinyButton({
  label = "Shiny Glow",
  className,
  ...props
}: ShinyButtonProps) {
  return (
    <button
      type="button"
      className={cn(
        "group relative overflow-hidden rounded-2xl bg-gradient-to-r from-zinc-900 via-zinc-800 to-zinc-900 px-6 py-3 text-sm font-semibold text-white border border-zinc-700/80 shadow-lg transition-all hover:shadow-blue-500/20 select-none cursor-pointer",
        className
      )}
      {...props}
    >
      <div className="absolute inset-0 -translate-x-full bg-gradient-to-r from-transparent via-white/20 to-transparent group-hover:animate-[shiny-sweep_1.2s_infinite]" />
      <span className="relative z-10 flex items-center gap-2">
        <Sparkles className="h-4 w-4 text-amber-400 group-hover:scale-125 transition-transform duration-300" />
        <span>{label}</span>
      </span>
      <style jsx global>{`
        @keyframes shiny-sweep {
          100% {
            transform: translateX(100%);
          }
        }
      `}</style>
    </button>
  );
}

export default ShinyButton;
